INSERT INTO regular_expressions (name, pattern) VALUES ('DE Atmos', '\b(ATMOS|DDPA)(\b|\d)');
INSERT INTO regular_expressions (name, pattern) VALUES ('DE TrueHD', 'True[ .-]?HD[ .-]?');
INSERT INTO regular_expressions (name, pattern) VALUES ('DE DTS-HD MA', '\b(dts[-_. ]?(ma|hd([-_. ]?ma)?|xll))(\b|\d)');
INSERT INTO regular_expressions (name, pattern) VALUES ('DE DTS-X', '\b(dts[-_. :]?x)\b(?!\d)');
INSERT INTO regular_expressions (name, pattern) VALUES ('DE Dolby Vision', '\b(DV|Dovi|Dolby[ .]?Vision)\b');
INSERT INTO regular_expressions (name, pattern) VALUES ('DE Dolby Vision (Without Fallback)', '(?<=^(?!.*(HDR|HULU|REMUX|BLU[-]?RAY)).*?)\b(DV|Dovi|Dolby[ .]?Vision)\b');
INSERT INTO regular_expressions (name, pattern) VALUES ('DE HDR', '\b(HDR(10|(?!\d))|HLG|PQ(10)?)\b');
INSERT INTO regular_expressions (name, pattern) VALUES ('DE HDR10+', '\bHDR10.?(\+|P(lus)?\b)');
INSERT INTO regular_expressions (name, pattern) VALUES ('DE SDR', '\bSDR\b');
INSERT INTO regular_expressions (name, pattern) VALUES ('DE 3D', '(?<=\b[12]\d{3}\b).*\b((Blu[-]?ray|BD)?3D|((H(alf)?|F(ull)?).?)?(O(ver)?.?U(nder)?|S(ide)?[\W_]?B(y)?.?S(ide)?))\b');
INSERT INTO regular_expressions (name, pattern) VALUES ('DE Movie Upscale', '(?<=\b[12]\d{3}\b).*\b(AI(US)?[ ._-]?(Enhanced)?|Up[ ._-]?scale(d)?|Re[ ._-]?Grade(d)?|Topaz[ ._-]?Enhanced)\b');
INSERT INTO regular_expressions (name, pattern) VALUES ('DE TV Upscale', '(?<=\b(?:S\d{1,3}|\d{3,4}p)\b).*\b(AI(US)?[ ._-]?(Enhanced)?|Up[ ._-]?scale(d)?|Re[ ._-]?Grade(d)?|Topaz[ ._-]?Enhanced)\b');
INSERT INTO regular_expressions (name, pattern) VALUES ('DE LQ Sources', '\b(CAM|CAMRip|DVDSCR|HDCAM|HDSCR|HDTC|HDTS|PDVD|PreDVDRip|SCREENER|TELECINE|TELESYNC|TSRip|WORKPRINT)\b');
INSERT INTO regular_expressions (name, pattern) VALUES ('DE Line/Mic Dubbed', '\b(LD|MD|AC3LD|AC3MD|E?AC3LD|E?AC3MD|DTSLD|DTSMD|Line[ .-]?Dubbed|Mic[ .-]?Dubbed)\b');
INSERT INTO regular_expressions (name, pattern) VALUES ('DE German DL Title', '(?=.*\bGERMAN\b)(?=.*\b((?<!WEB[ ._-])[DM]L|MULTi|ENG(lish)?|KOR(ean)?|JPN|JAP|FRE(nch)?|ITA|SPA)\b)');
INSERT INTO regular_expressions (name, pattern) VALUES ('DE AV1', '\bAV1\b');
INSERT INTO regular_expressions (name, pattern) VALUES ('DE Movie Extras', '(?<=\b[12]\d{3}\b).*\b(Extra(s)?|Bonus|Deleted[ ._-]?Scene(s)?|Extended[ ._-]?Clip(s)?|Special[ ._-]?Feature(s)?)\b');
INSERT INTO regular_expressions (name, pattern) VALUES ('DE LQ Groups (Radarr)', '^(126811|24xHD|41RGB|4K4U|AOC|AROMA|aXXo|AZAZE|BARC0DE|BAUCKLEY|BdC|beAst|BTM|C1NEM4|C4K|CDDHD|CHAOS|CHD|CiNE|CLEANUP|COLLECTiVE|CREATiVE24|CrEwSaDe|CTFOH|d3g|DDR|DNL|DRX|E|EPiC|EuReKA|FaNGDiNG0|Feranki1980|FGT|FMD|FRDS|FS|FZHD|GalaxyRG|GHD|GPTHD|HDHUB4U|(10bit-)?HDS|HDT|HDTime|HDWinG|iNTENSO|iPlanet|iVy|jennaortega(UHD)?|JFF|KC|KiNGDOM|KIRA|L0SERNIGHT|LAMA|Leffe|Liber8|LiGaS|LUCY|MarkII|MeGusta|Mesc|mHD|mSD|MTeam|MT|MySiLU|NhaNc3|nHD|nikt0|NoGr(ou)?p|nSD|OFT|Pahe(\.(ph|in))?|PATOMiEL|PRODJi|PSA|PTNK|RARBG|RBB|RDN|Rifftrax|RU4HD|SANTi|Scene|SHD|ShieldBearer|STUTTERSHIT|SUNSCREEN|SyncUP|TBS|TEKNO3D|Tigole|TIKO|VISIONPLUSHDR(-X|1000)?|WAF|WiKi|x0r|YIFY|YTS(.(MX|LT|AG))?|Zeus)$');
INSERT INTO regular_expressions (name, pattern) VALUES ('DE LQ Groups (Sonarr)', '^(126811|BRiNK|BTM|CHX|CTFOH|d3g|DepraveD|EVO|Feranki1980|FGT|FMD|GHOSTS|HiQVE|iNTENSO|iVy|JFF|KC|MeGusta|nhanc3|OFT|Pahe(\.(ph|in))?|PSA|SasukeducK|SHD|ShieldBearer|TBS|TG|VIDEOHOLE|worldmkv|XLF|Zero00)$');
